  ExternalIdentityMapping: 'ExternalIdentityMapping',
  KnownVendor: 'KnownVendor',
  Vendor: 'Vendor',
  VendorAssessment: 'VendorAssessment',
  VendorResearch: 'VendorResearch',
  VendorContact: 'VendorContact',
  VendorDocument: 'VendorDocument',
